from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class ULTestModelParams(SchemaObject):
    frc_index = SchemaField(name="frcIndex", not_null=True)
    phys_cell_id = SchemaField(name="physCellId", not_null=True)
    beam_pattern_id = SchemaField(name="beamPatternIdArray", not_null=True)
    prb_offset = SchemaField(name="prbOffset", not_null=True)
    reporting_time_interval = SchemaField(name="reportingTimeInterval", not_null=True)
    ru_mode = SchemaField(name="ruMode", not_null=True)
    nrarfcn = SchemaField(name="nrarfcn", optional=True)
    nrarfcn_ul = SchemaField(name="nrarfcnUl", optional=True)
    nrarfcn_dl = SchemaField(name="nrarfcnDl", optional=True)

    def __init__(self, frc_index=None, phys_cell_id=None, beam_pattern_id=None, prb_offset=None,
                 reporting_time_interval=None, ru_mode=None, nrarfcn=None, nrarfcn_ul=None, nrarfcn_dl=None):
        self.reporting_time_interval = reporting_time_interval
        self.ru_mode = ru_mode
        self.phys_cell_id = phys_cell_id
        self.nrarfcn = nrarfcn
        self.frc_index = frc_index
        self.beam_pattern_id = beam_pattern_id
        self.prb_offset = prb_offset
        self.nrarfcn_dl = nrarfcn_dl
        self.nrarfcn_ul = nrarfcn_ul


class ULTestModelResults(SchemaObject):
    time = SchemaField(name="time", not_null=True)
    rssi = SchemaField(name="rssi", not_null=True)
    throughput = SchemaField(name="throughput", not_null=True)
    received_bits = SchemaField(name="receivedBits", not_null=True)
    unreceived_bits = SchemaField(name="unreceivedBits", not_null=True)
    defective_bits = SchemaField(name="defectiveBits", not_null=True)
    received_blocks = SchemaField(name="receivedBlocks", not_null=True)
    unreceived_blocks = SchemaField(name="unreceivedBlocks", not_null=True)
    defective_blocks = SchemaField(name="defectiveBlocks", not_null=True)

    def __init__(self, time=None, rssi=None, throughput=None, received_bits=None, unreceived_bits=None,
                 defective_bits=None, received_blocks=None, unreceived_blocks=None, defective_blocks=None):
        self.time = time
        self.rssi = rssi
        self.throughput = throughput
        self.received_bits = received_bits
        self.unreceived_bits = unreceived_bits
        self.defective_bits = defective_bits
        self.received_blocks = received_blocks
        self.unreceived_blocks = unreceived_blocks
        self.defective_blocks = defective_blocks


class GetUplinkCPCONFIGV1(SchemaObject):
    ul_test_model_params = SchemaField(name="ulTestModelParams", klass=ULTestModelParams)
    ul_test_model_results = SchemaField(name="ulTestModelResults", klass=ULTestModelResults, many=True)

    def __init__(self, ul_test_model_params=None, ul_test_model_results=None):
        self.ul_test_model_params = ul_test_model_params
        self.ul_test_model_results = ul_test_model_results
        super(GetUplinkCPCONFIGV1, self).__init__()
